"""Kundenstamm als JSON-Datei."""

import json
from pathlib import Path


class CustomerStore:
    def __init__(self, path):
        self.path = Path(path)
        self.customers = {}

    def load(self):
        with self.path.open(encoding="utf-8") as handle:
            raw = json.load(handle)
        self.customers = {}
        for entry in raw:
            self.add(entry)
        return len(self.customers)

    def save(self):
        text = json.dumps(list(self.customers.values()), ensure_ascii=False, indent=2)
        self.path.write_text(text, encoding="utf-8")

    def add(self, customer):
        if customer["id"] in self.customers:
            raise ValueError(f"Kunde {customer['id']} existiert bereits")
        self.customers[customer["id"]] = customer

    def find_customer(self, customer_id):
        """Liefert den Kunden oder None, wenn die ID unbekannt ist."""
        return self.customers.get(customer_id)

    def recent_customers(self, limit):
        # Neueste zuerst: absteigend nach Anlagedatum (ISO-Datum, daher als Text sortierbar).
        ordered = sorted(self.customers.values(), key=lambda c: c["created"], reverse=True)
        return ordered[:limit]

