"""Rechnungen aus Bestellungen."""

from decimal import ROUND_HALF_UP, Decimal

MAX_POSITIONS = 50


class UnknownCustomer(Exception):
    pass


def validate_positions(positions):
    if not positions:
        raise ValueError("Bestellung ohne Positionen")
    if len(positions) > MAX_POSITIONS:
        raise ValueError(f"mehr als {MAX_POSITIONS} Positionen")


def order_total(order):
    """Preise kommen als Text ("9.90"), Mengen als int."""
    total = Decimal("0.00")
    for position in order["positions"]:
        total += Decimal(position["price"]) * position["qty"]
    return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def invoice_address(store, customer_id):
    customer = store.find_customer(customer_id)
    if customer is None:
        raise UnknownCustomer(customer_id)
    return "\n".join([customer["name"], customer["street"], f"{customer['zip']} {customer['city']}"])


def build_invoices(store, orders):
    """Eine Rechnung je Bestellung; Bestellungen unbekannter Kunden landen in skipped.

    Eine ungültige Bestellung bricht den ganzen Lauf mit ValueError ab, damit nie ein
    halber Rechnungslauf exportiert wird.
    """
    invoices, skipped = [], []
    for order in orders:
        validate_positions(order["positions"])
        try:
            address = invoice_address(store, order["customer_id"])
        except UnknownCustomer:
            skipped.append(order["id"])
            continue
        invoices.append({"order_id": order["id"], "address": address, "total": order_total(order)})
    return invoices, skipped

