"""Rechnungen als CSV."""

import csv


def export_csv(invoices, path):
    with open(path, "w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, delimiter=";")
        writer.writerow(["bestellung", "adresse", "summe"])
        for invoice in invoices:
            writer.writerow([invoice["order_id"], invoice["address"].replace("\n", ", "), f"{invoice['total']:.2f}"])
    return len(invoices)

touch.tests/test_store.py:
from app.store import CustomerStore

ANNA = {"id": "K1", "name": "Anna Berg", "street": "Hauptstr. 1", "zip": "10115", "city": "Berlin", "created": "2026-01-05"}


def test_save_and_load_roundtrip(tmp_path):
    store = CustomerStore(tmp_path / "kunden.json")
    store.add(ANNA)
    store.save()
    again = CustomerStore(tmp_path / "kunden.json")
    assert again.load() == 1
    assert again.find_customer("K1")["city"] == "Berlin"


def test_find_customer_unknown_is_none(tmp_path):
    assert CustomerStore(tmp_path / "kunden.json").find_customer("K9") is None


def test_add_rejects_duplicate(tmp_path):
    store = CustomerStore(tmp_path / "kunden.json")
    store.add(ANNA)
    try:
        store.add(ANNA)
    except ValueError:
        return
    raise AssertionError("doppelte ID angenommen")

