import pytest

from app.billing import build_invoices, order_total, validate_positions
from app.store import CustomerStore

ANNA = {"id": "K1", "name": "Anna Berg", "street": "Hauptstr. 1", "zip": "10115", "city": "Berlin", "created": "2026-01-05"}
ORDER = {"id": "B1", "customer_id": "K1", "positions": [{"price": "9.90", "qty": 2}, {"price": "0.20", "qty": 1}]}


def test_order_total_sums_positions():
    assert str(order_total(ORDER)) == "20.00"


def test_validate_rejects_empty_order():
    with pytest.raises(ValueError):
        validate_positions([])


def test_validate_rejects_far_too_many_positions():
    with pytest.raises(ValueError):
        validate_positions([{"price": "1", "qty": 1}] * 80)


def test_build_invoices_for_known_customer(tmp_path):
    store = CustomerStore(tmp_path / "kunden.json")
    store.add(ANNA)
    invoices, skipped = build_invoices(store, [ORDER])
    assert skipped == []
    assert invoices[0]["address"] == "Anna Berg\nHauptstr. 1\n10115 Berlin"
    assert str(invoices[0]["total"]) == "20.00"
